    "description": "10月4日是“世界动物日”。日前，记者走进位于新疆的阿尔金山国家级自然保护区观测记录野生动物，为藏野驴家族拍摄“全家福”。 阿尔金山国家级自然保护区位于新疆维吾尔自治区东南隅，面积约为4.5万平方公里，平均海拔4580米。这里雪山巍峨冰川遍布，草甸、湿地、湖泊、沙漠交错分布，是我国保存最为完整的高原荒漠生态系统之一。保护区现有藏野驴约5万头，野牦牛、藏羚等有蹄类野生动物突破12万头（只）。 记者：张啸诚、曹志恒、杜刚",
    "content": "10月4日是“世界动物日”。日前，记者走进位于新疆的阿尔金山国家级自然保护区观测记录野生动物，为藏野驴家族拍摄“全家福”。 阿尔金山国家级自然保护区位于新疆维吾尔自治区东南隅，面积约为4.5万平方公里，平均海拔4580米。这里雪山巍峨冰川遍布，草甸、湿地、湖泊、沙漠交错分布，是我国保存最为完整的高原荒漠生态系统之一。保护区现有藏野驴约5万头，野牦牛、藏羚等有蹄类野生动物突破12万头（只）。 记者：张啸诚、曹志恒、杜刚"
