    "description": "10月2日，第20届爱知·名古屋亚运会电竞项目在爱知天空展览馆落下帷幕。11个比赛日、11个小项、6大品类，来自不同厂商、不同引擎、不同终端形态的游戏，在同一座场馆里完成了亚运历史上规模最大的一届电竞角逐。 中国电竞队以3金1银成为本届亚运会赛场的最大赢家。但在奖牌榜之外，另一条“中国故事”贯穿了11天的亚运电竞：一套由中国企业自主研发的竞赛系统承担了全部11个小项的技术保障工作。它的名字叫ECS——Esports Competitio…",
    "content": "10月2日，第20届爱知·名古屋亚运会电竞项目在爱知天空展览馆落下帷幕。11个比赛日、11个小项、6大品类，来自不同厂商、不同引擎、不同终端形态的游戏，在同一座场馆里完成了亚运历史上规模最大的一届电竞角逐。 中国电竞队以3金1银成为本届亚运会赛场的最大赢家。但在奖牌榜之外，另一条“中国故事”贯穿了11天的亚运电竞：一套由中国企业自主研发的竞赛系统承担了全部11个小项的技术保障工作。它的名字叫ECS——Esports Competition Solution，腾讯电竞竞赛系统，是目前全球唯一应用于大型洲际综合运动会的…"
