    "author": "澎湃新闻记者 廖阳",
    "description": "“真实剧场的复杂环境，课堂里模拟不出来。排练场和剧场就是青年人才的‘第二课堂’，要在真实剧目排演和真实观众面前，打通成长的‘最后一公里’。”导演徐俊说。 10月3日-6日，第五届上海音乐学院国际音乐剧周如约而至，海内外专家、演艺企业代表、全国艺术院校师生齐聚现场，探讨中国音乐剧产业的人才缺口与原创发展，探索本土音乐剧人才培养新路径。 开幕现场 缩短校园到职业舞台的距离 说起音乐剧人才，人们的第一反应往往是能唱会跳的演员。如今，行业的人才…",
    "content": "“真实剧场的复杂环境，课堂里模拟不出来。排练场和剧场就是青年人才的‘第二课堂’，要在真实剧目排演和真实观众面前，打通成长的‘最后一公里’。”导演徐俊说。 10月3日-6日，第五届上海音乐学院国际音乐剧周如约而至，海内外专家、演艺企业代表、全国艺术院校师生齐聚现场，探讨中国音乐剧产业的人才缺口与原创发展，探索本土音乐剧人才培养新路径。 开幕现场 缩短校园到职业舞台的距离 说起音乐剧人才，人们的第一反应往往是能唱会跳的演员。如今，行业的人才困境和需求变了：兼具剧本创作、项目制作、剧场运营、市场研判能力的全链条复合型人才…"
