    "description": "10月3日，广西平南县林业局发布《情况通报》称，近日，有群众举报在平南县丹竹镇白马村发现有人架网实施非法捕鸟。接报后，我局会同公安、生态环境、农业农村等部门迅速行动，立即赶赴现场进行调查处置，现场共依法拆除捕鸟点位架设的捕鸟网5处。目前公安机关已依法传唤相关涉案人员，案件正在进一步侦办中。 稍早前，有志愿者反映称，他们在野外巡查中发现，平南县丹竹镇河儿屯、511乡道状元河一带的水面上，架设着大面积非法捕鸟粘网。这套装置相当“专业”：水里…",
    "content": "10月3日，广西平南县林业局发布《情况通报》称，近日，有群众举报在平南县丹竹镇白马村发现有人架网实施非法捕鸟。接报后，我局会同公安、生态环境、农业农村等部门迅速行动，立即赶赴现场进行调查处置，现场共依法拆除捕鸟点位架设的捕鸟网5处。目前公安机关已依法传唤相关涉案人员，案件正在进一步侦办中。 稍早前，有志愿者反映称，他们在野外巡查中发现，平南县丹竹镇河儿屯、511乡道状元河一带的水面上，架设着大面积非法捕鸟粘网。这套装置相当“专业”：水里泡着逼真的诱鸟模具，岸边架着持续发声的诱鸟器，细丝网横在水面低空——鸟群被声音和…"
