    "description": "《红楼梦》大旨谈情，大观园的少年儿女把滚烫心意藏于日常，宝黛的灵魂相知、宝玉与晴雯的知己相托，万般情愫，坦荡而本真。2026年国庆假期，第十七届曹雪芹文化艺术季在国家植物园曹雪芹西山故里举办，以“情”为脉络，邀所有红迷与文艺爱好者共同见证与参与。 “红楼园游会”：和妙玉运送煮茶雪水、复刻刘姥姥宴席夹鸽子蛋 《红楼梦》及曹雪芹笔下最受喜欢的经典人物将再次穿越时空和读者见面。 北京曹雪芹学会介绍，《红楼梦》中的经典桥段被化用到艺术季的“红楼…",
