    "content": "新华社拉萨10月4日电 题：高原旅游别急着洗澡，休整速洗防感冒 蒋梦辰、王思俊 壮丽的雪山、风格别致的藏袍、香浓可口的酥油茶……西藏独特的自然风光和人文风情让游客心驰神往，但“高反”也让不少游客心存顾虑。“上高原一定别洗头”“适应几天再洗澡”“在高原千万别感冒”等各类高原旅游小贴士在社交平台传播，引发网友讨论。 专家就此指出，与氧气充沛的平原地区不同，高原地区具有低压、低氧的环境特点。洗澡，在高原特殊环境下潜藏一定风险。 拉萨市人民医院急诊科主任医师张一杰说，高原低压低氧环境会持续让人体心肺系统承压。人体内血氧含量…"
