    "content": "2026年10月04日 山势起伏，草原舒展，远处有一座座旧厂房。这里是位于青海省海北藏族自治州海晏县西海镇的原子城纪念馆，我国第一个核武器研制基地——原国营二二一厂所在地，“两弹一星”精神在此孕育诞生。 今年是中国工农红军长征胜利90周年。90年前，革命先辈爬雪山过草地，用脚步丈量信仰；60多年前，另一群人挺进金银滩草原，用算盘算出“争气弹”。两段历史相隔数十年，却有着共同的精神底色。 在原子城纪念馆，副馆长杜文林讲起筹备展览的往事。 “‘苦不苦，想想长征两万五’，这是寻访中听到最多的一句话。”杜文林感慨，核武器研…"
