    "description": "2026年10月04日 第四届“读懂中国式现代化”工作坊调研团近日在浙江衢州参访。作为2026“中巴文化年”系列活动，工作坊以“走进共同富裕”为主题，邀请来自巴西本土及在华的巴西学界、媒体界和商界代表，通过实地调研等形式，深入了解中国式现代化进程中推进共同富裕的实践，探访城乡融合发展、改善民生等方面的实践案例，增进巴西各界对中国发展道路和发展理念的了解，促进中巴人文交流与文明互鉴。图为巴西调研团在衢州市非遗馆内参观。 新华社记者 戴明轩…",
