    "description": "2026年10月04日 在位于巴西里约热内卢的巴西国家历史博物馆展厅里，一张摆放着中式佳肴模型的圆桌吸引不少观众驻足。“和鼎调羹——中国古代饮食文化展”正在这里举行，一件件跨越千年的文物，讲述着中国人的饮食记忆与生活智慧。 从“杂食养益”到“熟食热饮”，再到“敬天事礼”“悦目怡心”“美美与共”，关于中国饮食的文明图景徐徐铺展开来。来自中国国家博物馆的百余件（套）文物，不仅呈现了从饮食结构、烹饪方式到礼仪审美的完整体系，也勾勒出中国社会生…",
    "content": "2026年10月04日 在位于巴西里约热内卢的巴西国家历史博物馆展厅里，一张摆放着中式佳肴模型的圆桌吸引不少观众驻足。“和鼎调羹——中国古代饮食文化展”正在这里举行，一件件跨越千年的文物，讲述着中国人的饮食记忆与生活智慧。 从“杂食养益”到“熟食热饮”，再到“敬天事礼”“悦目怡心”“美美与共”，关于中国饮食的文明图景徐徐铺展开来。来自中国国家博物馆的百余件（套）文物，不仅呈现了从饮食结构、烹饪方式到礼仪审美的完整体系，也勾勒出中国社会生活与文化变迁的轨迹。 “‘和鼎调羹’既体现了‘调和五味’的烹饪实践，又象征着中国…"
