    "description": "2026年10月04日 启航向海！ 今年9月，平陆运河，新中国成立以来建设的首条通江达海的大运河正式建成通航。 劈山开岭、通江达海，这条全长134.2公里的运河，按内河Ⅰ级航道标准建设，可通航5000吨级船舶，是国内通航等级最高的运河，一举创造多项“世界之最”。 自2022年8月动工，1400多个昼夜里，两万多名建设者奋战在崇山峻岭之间，总投资超700亿元，向海之路由此打通。不只平陆运河，京杭运河与小清河航道连通工程开工，浙赣、赣粤、湘…",
    "content": "2026年10月04日 启航向海！ 今年9月，平陆运河，新中国成立以来建设的首条通江达海的大运河正式建成通航。 劈山开岭、通江达海，这条全长134.2公里的运河，按内河Ⅰ级航道标准建设，可通航5000吨级船舶，是国内通航等级最高的运河，一举创造多项“世界之最”。 自2022年8月动工，1400多个昼夜里，两万多名建设者奋战在崇山峻岭之间，总投资超700亿元，向海之路由此打通。不只平陆运河，京杭运河与小清河航道连通工程开工，浙赣、赣粤、湘桂运河等工程进入论证阶段……一段时间以来，新一轮运河修建热潮引发广泛关注。 有人…"
