    "description": "2026年10月04日 房刘敏摄 \"> 张书宁摄 \"> 张书宁摄 \"> 张书宁摄 \"> 张书宁摄 \"> 张书宁摄 \"> 辽宁省朝阳市朝阳县现有7个中国传统村落。2022年入选传统村落集中连片保护利用示范县以来，该县秉持“整体保护、连片发展”思路，以中国传统村落为核心、省级传统村落为补充，将传统村落与县域旅游资源串珠成链，探索出保护修缮、文旅融合、司法保障协同推进的连片保护利用路径。2023年起，该县利用专项资金实施151个保护项目，目前…",
