    "description": "2026年10月04日 广东省博物馆提供 \"> 广东省博物馆提供 \"> 走进博物馆，你也许有过这样的疑问：书画展厅为何总是显得有些昏暗？橱窗里的钻石、玉石为何格外璀璨？大厅里明明亮堂堂，却几乎看不见一盏灯？答案，都藏在同一样东西里——光。它被精心设计，塑造着空间的氛围，凸显着展品的质感，也在守护着藏品的生命。广东省博物馆陈列设计师李聪向记者道出博物馆光的运用背后的门道。 为什么书画展厅总是有些昏暗？ 在李聪看来，光是展览的语言，是展品与…",
    "content": "2026年10月04日 “凝眸——16至20世纪典藏珍宝艺术展”上，设计者通过光影运用为清代点翠凤冠营造璀璨夺目的视觉效果。 广东省博物馆提供 \"> “绘冠南天——粤藏宋元书画特展”展厅中，布展人根据书画文物特点，设计光照方案。 广东省博物馆提供 \"> 走进博物馆，你也许有过这样的疑问：书画展厅为何总是显得有些昏暗？橱窗里的钻石、玉石为何格外璀璨？大厅里明明亮堂堂，却几乎看不见一盏灯？答案，都藏在同一样东西里——光。它被精心设计，塑造着空间的氛围，凸显着展品的质感，也在守护着藏品的生命。广东省博物馆陈列设计师李聪向…"
