    "description": "2026年10月04日 谢贵明摄 \"> 罗鸿贤摄 \"> 福建省泉州市清源山东岳山麓，泉州少林寺依山而建。走进泉州少林寺，古木参天，禅音袅袅。作为南派少林武术的发祥地，这里又被称为“南少林”。 南少林武术的生命力，不只在古刹演武堂。正值课间操期间，泉州市丰泽区第二实验小学东海校区的操场上，传来阵阵拳声。学校将五祖拳引入课堂，口传心授的武学招式化为生动有趣的体育课，一招一式虎虎生威。 这门武学，已有1300多年传承史。据《西山杂志》载，泉州…",
    "content": "2026年10月04日 少林武僧团成员正在进行武术表演。 谢贵明摄 \"> 航拍泉州少林寺。 罗鸿贤摄 \"> 福建省泉州市清源山东岳山麓，泉州少林寺依山而建。走进泉州少林寺，古木参天，禅音袅袅。作为南派少林武术的发祥地，这里又被称为“南少林”。 南少林武术的生命力，不只在古刹演武堂。正值课间操期间，泉州市丰泽区第二实验小学东海校区的操场上，传来阵阵拳声。学校将五祖拳引入课堂，口传心授的武学招式化为生动有趣的体育课，一招一式虎虎生威。 这门武学，已有1300多年传承史。据《西山杂志》载，泉州少林寺原名“镇国东禅少林寺”…"
