    "description": "2026年10月04日 江西省博物馆提供 \"> 江西省博物馆提供 \"> 在江西省博物馆“虎踞江南——新干大墓与青铜王国”展览中，一尊商代双面神人青铜头像静静伫立。江西省博物馆馆标的核心视觉，正源自这件国宝的剪影。它出土于江西省吉安市新干县大洋洲商代大墓，是迄今所见唯一的双面青铜头像，被称为“江南青铜王国”的精神图腾。 记者：江西省博物馆的馆标核心视觉，源自这件双面神人青铜头像的剪影。一件3000多年前的商代文物，凭什么能代表今天的江西省…",
