    "author": "",
    "description": "2026年10月04日 王 劲供图 \"> 节假日期间，很多人选择以脚步丈量大地，在行走中阅读祖国山河、感受时代气象。来到陕西榆林红石峡，便会发现，历史就刻在崖壁之上。站在栈道仰望，80余件擘窠大字层叠错落、凌空雄峙。这里被誉为“塞上碑林”，但我更愿将它看作是一部刻在丹崖上的史书——写的是书法，也是山河壮志与家国情怀。 榆林位于黄土高原与毛乌素沙地的衔接地带，曾为明代九边重镇之一延绥镇治所。特殊的地缘让这里既是烽烟不息的军事要塞，也是农耕…",
    "content": "2026年10月04日 红石峡摩崖题刻。 王 劲供图 \"> 节假日期间，很多人选择以脚步丈量大地，在行走中阅读祖国山河、感受时代气象。来到陕西榆林红石峡，便会发现，历史就刻在崖壁之上。站在栈道仰望，80余件擘窠大字层叠错落、凌空雄峙。这里被誉为“塞上碑林”，但我更愿将它看作是一部刻在丹崖上的史书——写的是书法，也是山河壮志与家国情怀。 榆林位于黄土高原与毛乌素沙地的衔接地带，曾为明代九边重镇之一延绥镇治所。特殊的地缘让这里既是烽烟不息的军事要塞，也是农耕文明与游牧文明交融之地。一代代戍边将帅、文臣士子把胸中抱负、山…"
