    "content": "新华社日本名古屋10月4日电 据中国体育代表团4日消息，帆船选手毕焜将担任爱知·名古屋亚运会闭幕式中国代表团旗手。 毕焜在本届亚运会帆船项目男子水翼帆板比赛中成功卫冕，实现亚运三连冠。从2018年雅加达亚运会的帆板RS:X级，到杭州亚运会和本届亚运会的水翼帆板iQFOiL级，他跨越两个几乎完全不同的级别，连续三届亚运会夺冠。 本届亚运会闭幕式将于10月4日晚举行。 10月3日，冠军中国选手毕焜在颁奖仪式上。当地时间10月3日，爱知·名古屋亚运会帆船项目男子水翼帆板颁奖仪式举行。新华社记者 邓华 摄"
