    "content": "最近，日本企业们都在忙一件事，涨价。 《日经亚洲》报道，日本食品巨头格力高10月出货的百力滋品牌等164款商品提价3%—15%；养乐多上调12款产品价格；油炸豆制零食Miino涨价；婴儿配方奶粉Puremilk每罐上涨15%；日本烟草出产的烟草棒涨价40日元…… 日本帝国数据库调查显示，10月，日本市场共有3153种食品涨价，叠加9月近5000种涨价食品(约为去年同期3倍)，这波年内最大涨价潮，正直扑日本人餐桌。 整个日本，为何困在一个“涨”字里？ 简单来说，日本正遭遇全球地缘风暴、国内成本困局和日元贬值等多重夹击…"
