    "content": "新华社武汉10月3日电（记者龚联康）秋阳斜照，武汉大余湾古村的黛瓦屋顶上，辣椒、玉米、南瓜、板栗等农作物错落摆放，仿佛把一季收成都摊到了阳光下……国庆假期，大余湾古村晒秋节正在进行，延续数百年的农耕习俗，融入农事体验、市集互动等新元素，古村烟火气再添一番新意。 民居屋顶上晾晒的各色谷物果蔬。新华社记者 龚联康 摄 “南方空气潮湿，秋收后，人们把收获的谷物果蔬摊在屋顶、院坝和巷道旁，借着秋日阳光风干储存，这便是晒秋。”位于武汉市黄陂区的大余湾景区负责人卢千说。 大余湾古村坐落在大别山南麓的木兰山脚下，是“中国历史文化…"
