    "content": "新华社利雅得10月3日电（记者罗晨）沙特阿拉伯主导的多国联军3日称，也门胡塞武装当天有关袭击沙特首都利雅得的说法“具有误导性”。 据沙特《中东报》3日报道，多国联军发言人图尔基·马利基对该报表示，胡塞武装近期在也门西南部塔伊兹省及其他战线遭受人员损失，这让该武装试图寻求“虚假胜利”。他称，胡塞武装此举意在转移外界对其损失的关注。 胡塞武装3日早些时候称，该组织使用弹道导弹和无人机袭击了位于沙特首都利雅得的一处沙特阿美公司石油设施。袭击实现预定目标，“直接命中”导致目标地点起火。这是对沙特袭击也门萨那及其他胡塞武装控…"
