    "description": "新华社平壤10月4日电（记者王天僚） 据朝中社4日报道，朝鲜3日凌晨在东部地区进行了中程战略导弹发射训练。朝鲜劳动党总书记、国务委员长金正恩现场观摩训练。 报道说，用于训练的导弹命中了设定在朝鲜东部海域的目标。训练旨在让操纵高超音速战略武器系统的导弹兵熟练掌握火力操纵能力。 金正恩表示，要以强大的遏制力管控各种威胁，为国家建设保证安全环境。",
