    "content": "新华社新德里10月3日电 印度外交部3日发表声明称，印方当天召见巴基斯坦驻印度高级专员公署临时代办，就印方所指巴方“为非法跨境渗透提供便利”的行为提出强烈抗议。 印方在声明中驳斥巴方就2日发生在印度旁遮普邦菲罗兹布尔段印巴边界附近事件所提出的指控，称相关指控“毫无根据且别有用心”。 声明称，当时有三人越过边界“渗入”印度境内，印边境安全部队多次警告要求其返回，但对方继续向边境围栏方向移动。印方称，由于对方构成“迫在眉睫的安全威胁”，印边境安全部队遂采取行动。 声明称，“此次事件凸显巴基斯坦境内武装贩毒团伙反复跨境活…"
