    "content": "新华社北京10月3日电 美国纽约州州长凯茜·霍楚尔2日说，因该州法律漏洞，康奈尔大学齐菲兄弟会成员轮奸案嫌疑人此前没能被检方起诉，她将推动修订相关法律，以确保性侵案件嫌疑人被依法追究罪责。 该案受害女子9月16日向纽约州最高法院提交诉状，对齐菲兄弟会和康奈尔大学提起民事诉讼。她说，2024年10月19日深夜，她在齐菲兄弟会宿舍遭该兄弟会2名成员灌酒并强迫服用氯胺酮，随后遭到该兄弟会7名成员性侵直至次日凌晨5时45分。受害人提供的关键证据是一张事发时该兄弟会在社交软件上群聊的截图。 纽约州检察官9月28日宣布重启对该…"
