    "content": "新华社北京10月3日电 9月30日，阿联酋迪拜航空公司一架飞往以色列的航班发生副驾驶刺伤机长事件，客机最终化险为夷，安然降落。主导事件调查的阿联酋检方3日说，涉事副驾驶企图实施“恐怖主义行为”。多家媒体根据政府人士披露的以及社交媒体上的信息，拼凑出这名副驾驶的大致情况。 9月30日，一架载有迪拜航空涉事航班乘客的替代航班即将降落在以色列特拉维夫的本-古里安国际机场。新华社发（吉尔·科恩·马根摄） 身份未公开确认 阿联酋总检察长哈马德·赛义夫·沙姆西3日说，副驾驶在飞行途中开始实施其计划，在驾驶舱内袭击机长，并企图控…"
