    "content": "（本文首发于南方人物周刊） 南方人物周刊记者 孙凌宇 发自：上海 责任编辑：杨静茹 （SleepNoMore/图） 这是一场事先声张的离别。早在7月13日，上海麦金侬酒店外墙就挂上了一块10平米大的倒计时展示板，预示着在酒店内上演的沉浸式戏剧《不眠之夜》即将收官。当天，红色的展示板上写着“距酒店主人今夏辞别申城远行仅余50夜”，此后，数字页逐夜翻动，直至2026年8月30日，这场在此上演了10年的梦终于落幕。 梦境的开始，一片漆黑，摸着墙壁经过几道狭窄的走廊，手持同样数字纸牌的观众被分在同一批，面面相觑地陆续抵达电…"
