    "content": "新华社北京10月3日电 以色列机场管理局网站3日发布的信息显示，在阿联酋迪拜航空公司暂停所有往返以色列的航班后，首架搭载以色列滞留旅客的以民航客机当天凌晨从迪拜飞抵特拉维夫。 根据抵达航班信息，这趟航班由阿基亚以色列航空公司运营，2日从迪拜起飞，3日凌晨1时许降落在特拉维夫附近的本-古里安机场。 这是9月30日拍摄的以色列特拉维夫附近的本-古里安国际机场。新华社发（吉尔·科恩·马根摄） 9月30日，迪拜航空从迪拜飞往特拉维夫的一架航班在飞行途中发生安全事件，该客机改道并安全降落在沙特阿拉伯塔布克机场。随后，迪拜航空…"
