    "content": "新华社埃及阿拉曼10月3日电（记者姚兵 徐皓夫）埃及总统塞西3日表示，面对地缘政治紧张和经济挑战，非洲应增强自身能力和韧性，深化经济一体化以应对全球形势快速变化。 塞西当天在于埃及阿拉曼新城举行的阿拉曼非洲论坛开幕式致辞中说，此次论坛旨在弥合信息鸿沟，加强非洲企业和投资者之间的联系，推动落实《非洲大陆自由贸易区协定》。非洲拥有丰富的人力和自然资源，应通过加强合作推动发展和繁荣。 非洲联盟发展署首席执行官纳勒多瑟·贝克莱-托马斯表示，尽管面临诸多挑战，非洲大陆仍拥有巨大潜力，应进一步动员非洲内部资本，推动更多项目落地…"
