    "content": "新华社东京10月3日电（记者陈泽安 蓝建中）据日本媒体3日报道，当天日本八丈岛附近海域有8名潜水者在失联约4小时后获救。 据日本下田海上保安部当天消息，当地时间3日13时50分左右，该部接到通报称，八丈岛附近海域有8名潜水者没有按原定时间浮出水面。 据日本TBS电视台报道，8名潜水者包括1名潜水教练和7名游客，他们于当地时间11时30分左右开始潜水，原定约1小时后浮出水面，但直到有关部门接到报告时一直无人浮出。当地时间16时40分左右，8人被发现并救起。 据日本共同社3日晚报道，8人在潜水地点东北方向约14公里处被…"
