    "pub_date": "2026-10-03 22:19:08",
    "author": "吴晓颖",
    "description": "新华社成都10月3日电（记者吴晓颖）10月3日，由中国地质大学（北京）牵头、尼泊尔科学院协同组建的地质灾害应急跨境科学考察队在成都理工大学举行出征仪式，国内专家将于10月4日从成都启程赴尼泊尔，开展跨境冰冻圈与岩石圈巨灾应急联合科考。 据悉，本次科考由中尼双方共同组建，中国科学院院士王成善与尼泊尔科学院院士比沙尔·乌普雷蒂共同担任首席科学家。科考队伍包含了十余家高校与科研院所的50余名科研人员。 “此次跨境应急联合科考，科研人员将抢抓灾…",
    "content": "新华社成都10月3日电（记者吴晓颖）10月3日，由中国地质大学（北京）牵头、尼泊尔科学院协同组建的地质灾害应急跨境科学考察队在成都理工大学举行出征仪式，国内专家将于10月4日从成都启程赴尼泊尔，开展跨境冰冻圈与岩石圈巨灾应急联合科考。 据悉，本次科考由中尼双方共同组建，中国科学院院士王成善与尼泊尔科学院院士比沙尔·乌普雷蒂共同担任首席科学家。科考队伍包含了十余家高校与科研院所的50余名科研人员。 “此次跨境应急联合科考，科研人员将抢抓灾后黄金窗口期，到境外源区开展应急调查，获取珍贵的野外观测数据。”中国科学院院士王…"
