    "description": "截至3日晚，中国代表团在爱知·名古屋亚运会上共收获169金89银83铜。由于4日闭幕日无中国队选手参赛，代表团最终锁定该成绩，实现自1982年新德里亚运会以来连续第十二届位居亚运会金牌榜首位。169枚金牌也刷新了中国代表团亚运会境外参赛金牌数量纪录。 中国代表团此前的境外参赛金牌数纪录是多哈亚运会上的165金。多哈亚运会共设39个大项、424个小项，中国队参加了其中37个大项、362个小项；爱知·名古屋亚运会设43个大项、469个小项，…",
    "content": "截至3日晚，中国代表团在爱知·名古屋亚运会上共收获169金89银83铜。由于4日闭幕日无中国队选手参赛，代表团最终锁定该成绩，实现自1982年新德里亚运会以来连续第十二届位居亚运会金牌榜首位。169枚金牌也刷新了中国代表团亚运会境外参赛金牌数量纪录。 中国代表团此前的境外参赛金牌数纪录是多哈亚运会上的165金。多哈亚运会共设39个大项、424个小项，中国队参加了其中37个大项、362个小项；爱知·名古屋亚运会设43个大项、469个小项，中国队参加了其中38个大项、369个小项。 9月19日，中国体育代表团在开幕式上…"
