    "author": "田子骏",
    "description": "中秋国庆假期，广西大新县的明仕田园景区，连片稻田铺展在喀斯特峰丛之间，游客沿着田埂散步、拍照。 家住深圳的钟炜和家人乘动车抵达北海后一路自驾而来。“我们想找一处安静的地方休息，看看稻田，避开人流高峰。”他说，一家人在明仕田园住了两天，没有把行程排成密集的景点打卡。 来自河北邯郸的游客李娜带着孩子自驾广西，她平日出行多选择入住星级酒店，此次改住当地的田园民宿，让孩子近距离观察喀斯特地貌。“体验感很好，下次想约上朋友，多住几天。”李娜说。 …",
