    "description": "新华社伦敦10月3日电（记者张家伟）英国南安普敦大学日前发布消息说，一项大规模研究显示，拼图、学习新技能、参加社交活动等简单的脑力活动，配合运动和健康饮食建议，有助改善老年人的认知障碍。 研究人员对超过1.15万名60岁至85岁、存在不同程度认知障碍的人进行了为期12个月的研究。参与者被分成三组：第一组参与者获得了研究人员提供的有针对性的简要建议，包括通过体育锻炼、健康饮食和脑力刺激活动来维持认知健康；第二组还可使用提供脑力训练和相关建…",
    "content": "新华社伦敦10月3日电（记者张家伟）英国南安普敦大学日前发布消息说，一项大规模研究显示，拼图、学习新技能、参加社交活动等简单的脑力活动，配合运动和健康饮食建议，有助改善老年人的认知障碍。 研究人员对超过1.15万名60岁至85岁、存在不同程度认知障碍的人进行了为期12个月的研究。参与者被分成三组：第一组参与者获得了研究人员提供的有针对性的简要建议，包括通过体育锻炼、健康饮食和脑力刺激活动来维持认知健康；第二组还可使用提供脑力训练和相关建议的网站；第三组则额外获得护士等工作人员通过面谈、电话或电子邮件提供的简短咨询。…"
