    "description": "新华社阿布贾10月3日电（记者洪泽华）尼日利亚中部高原州政府3日说，该州2日发生一起交通事故，造成20人死亡、5人受伤。 高原州政府说，共有4辆车在该州一条公路上发生碰撞。初步调查显示，有车辆因刹车失灵而失控。伤者已被送往当地医院接受救治。 有目击者说，一辆载有乘客的巴士下坡时失控，撞上了其他车辆，其中一辆是货车。",
