    "description": "新华社成都10月3日电 题：一块田里的粮食增产秘笈——四川秋收粮食观察 新华社记者高健钧、袁波 眼下，四川秋收接近尾声。记者在四川多个粮食生产大县走访发现，粮食种植单产的提升让种植户增产又增收，在这背后，是良种、良田、良法、良机等科学种粮秘笈发挥的作用。 不久前，在四川丘陵地区农业大县三台县塔山镇宝林村，几台收割机在一片稻田中轰轰隆隆收割作业，不一会儿，200多亩稻田中金黄的稻谷就顺着卸粮口倒进机耕道旁的运粮车，称重一算，每亩收获的稻谷…",
    "content": "新华社成都10月3日电 题：一块田里的粮食增产秘笈——四川秋收粮食观察 新华社记者高健钧、袁波 眼下，四川秋收接近尾声。记者在四川多个粮食生产大县走访发现，粮食种植单产的提升让种植户增产又增收，在这背后，是良种、良田、良法、良机等科学种粮秘笈发挥的作用。 不久前，在四川丘陵地区农业大县三台县塔山镇宝林村，几台收割机在一片稻田中轰轰隆隆收割作业，不一会儿，200多亩稻田中金黄的稻谷就顺着卸粮口倒进机耕道旁的运粮车，称重一算，每亩收获的稻谷达到1600余斤。 在四川丘陵地区农业大县三台县塔山镇宝林村，几台收割机在一片稻…"
