    "content": "中新网北京10月3日电 (记者 应妮)国家图书馆“四季童读·书香校园行”专项行动日前在京正式启动。这是《全民阅读促进条例》实施后，国家图书馆面向校园推出的又一少儿阅读推广举措，标志着“四季童读”从公共图书馆系统向校园场景系统性延伸。"
