    "title": "“人工智能治理研究的延续与变革”学术研讨会在京举办",
    "link": "https://www.chinanews.com.cn/gn/2026/10-03/10707631.shtml",
    "pub_date": "2026-10-03 21:07:31",
    "author": "",
    "description": "中新网北京10月3日电 (曾玥 贾海语)“人工智能治理研究的延续与变革”学术研讨会暨中国科技新闻学会数字传播伦理专委会年会(2026)近日在中国传媒大学举办。来自新闻传播学、公共管理、国际关系、政治学等多个学科领域的专家学者，围绕人工智能治理的经典理论、前沿问题、政策实践以及全球治理与伦理问题展开深入交流。",
    "content": "中新网北京10月3日电 (曾玥 贾海语)“人工智能治理研究的延续与变革”学术研讨会暨中国科技新闻学会数字传播伦理专委会年会(2026)近日在中国传媒大学举办。来自新闻传播学、公共管理、国际关系、政治学等多个学科领域的专家学者，围绕人工智能治理的经典理论、前沿问题、政策实践以及全球治理与伦理问题展开深入交流。"
