    "content": "新华社北京10月3日电（记者孙鹏程）记者10月3日从公安部交通管理局获悉，国庆假期第三天，全国道路交通流量持续回落，但仍处于高位运行。各级公安交管部门针对假期出行特点，科学调配勤务部署，加强对景区周边等重点路段疏导管控，持续严管严查交通违法，广泛开展交通安全宣传提示，全力保障人民群众假期出行平安顺畅。截至19时，全国道路交通总体平稳有序。 公安部交通管理局提醒广大驾驶人和出行群众，密切关注天气情况变化，合理安排出行时间和路线，雨雾天气行车要“减速、亮尾、控距”，确保安全驾驶。假期聚会多，切勿酒后驾车，行车过程中全程…"
