    "content": "新华社哈尔滨10月3日电 题：黑龙江：加强线路巡检 建设坚强电网 新华社记者刘赫垚 清晨，位于祖国最东端的黑龙江抚远迎来第一缕阳光，国网抚远供电公司的工作人员开始了一天的巡线工作。 抚远黑瞎子岛毗邻边境水域，岛上线路是抚远供电辖区运维环境最为艰苦的区段之一。岛上沼泽、滩涂、荒草甸交错，缺少巡线便道，一不小心就可能踏入淤泥。巡线工人吴迪、仲昭欣两人相互搀扶、提醒，逐杆开展巡检。 上午10时许，两人巡检至东岗线77号电杆。杆塔紧邻界江水域，空气湿度大，容易对杆塔、导线和金具造成腐蚀。“77号杆耐张线夹、挂环及部分螺栓锈…"
