    "content": "新华社呼和浩特10月3日电 题：“塞外粮仓”丰收忙——内蒙古秋粮生产一线观察 新华社记者李云平、连振 目前，作为全国玉米主要产区之一的内蒙古自治区正处于玉米收获期，广大农户利用有利天气条件抓紧秋收，确保增产增收。 连日来，在地处内蒙古西部地区的巴彦淖尔市临河区八一乡八一村玉米种植基地，收割机的轰鸣声此起彼伏，农机手驾驶小型收割机收割玉米秸秆，把分拣出来的玉米棒倒进拖拉机车斗中，农户及时将玉米棒运送回家。八一村村民丁艳君说：“我家种了80亩玉米，过去依靠人工收割需要十来天，现在利用收割机只要一天就能完成了。” 巴彦淖…"
