    "content": "新华社日本丰田10月3日电 题：亚运男足将士：说好了“带奖牌回国”，那就一起去兑现！ 新华社记者王海洲、肖世尧 对彭啸来说，走向罚球点之前的等待，最难熬。看着队友将上一粒点球罚进，他知道，接下来这一脚，可能决定奖牌的归属。“我知道，可能我打进，我们就赢了。”他说。 10月3日，彭啸在点球大战中射门得分。新华社记者 贾浩成 摄 中国队与乌兹别克斯坦队在爱知·名古屋亚运会男足铜牌赛中战成2:2，胜负交给点球大战。等待终于结束，彭啸将球罚进。中国队赢了，“带一块奖牌回去”的心愿，在此刻成为现实。 球员们聚在一起庆祝。守门…"
