    "pub_date": "2026-10-03 20:02:42",
    "author": "李恒",
    "description": "新华社北京10月3日电（记者李恒）正值国庆长假，有人外出旅游，有人选择在家彻底放松。专家提醒，长时间躺着不动，可能正在悄悄加速一种并非老年人“专属”的健康问题——肌少症。 中国中医科学院广安门医院风湿病科主任医师焦娟介绍，肌少症是指肌肉的流失大于肌肉的增加，虽然它常在老年人中出现，但是肌肉流失并不是到了老年才突然发生的，中年以后就应该开始关注肌肉健康，长期缺乏运动、营养不良以及患有慢性病的人群也应留意肌肉量和肌肉力量下降。 哪些情况要警…",
    "content": "新华社北京10月3日电（记者李恒）正值国庆长假，有人外出旅游，有人选择在家彻底放松。专家提醒，长时间躺着不动，可能正在悄悄加速一种并非老年人“专属”的健康问题——肌少症。 中国中医科学院广安门医院风湿病科主任医师焦娟介绍，肌少症是指肌肉的流失大于肌肉的增加，虽然它常在老年人中出现，但是肌肉流失并不是到了老年才突然发生的，中年以后就应该开始关注肌肉健康，长期缺乏运动、营养不良以及患有慢性病的人群也应留意肌肉量和肌肉力量下降。 哪些情况要警惕？焦娟列举了几个危险信号：拧瓶盖、提重物费劲，行走变慢，爬楼或起坐更加困难，甚…"
